(6353265, 940308, 126709, '<td valign="top">I almost used a canteen also.  I think the shallow dof takes away from this.  Still like the pic.</td>', 'I almost used a canteen also.  I think the shallow dof takes away from this.  Still like the pic.', '2011-03-16 12:41:54.000000', NULL, 1),
(6353266, 940263, 126709, '<td valign="top">Brother, the bottle gets lost in the sky.  Sitting in front of the body armor and portrait would convey the message better I think.  Stay safe, De Oppresso Liber.</td>', 'Brother, the bottle gets lost in the sky.  Sitting in front of the body armor and portrait would convey the message better I think.  Stay safe, De Oppresso Liber.', '2011-03-16 12:41:56.000000', NULL, 1),
(6353268, 940121, 126709, '<td valign="top">Love the light and composition.  Definitely in the running for a ribbon I think.</td>', 'Love the light and composition.  Definitely in the running for a ribbon I think.', '2011-03-16 12:42:09.000000', NULL, 1),
(6353269, 939870, 126709, '<td valign="top">I like the lines and colors.  Nice light.</td>', 'I like the lines and colors.  Nice light.', '2011-03-16 12:42:13.000000', NULL, 1),
