(6353280, 940752, 126709, '<td valign="top">Love the color and light.</td>', 'Love the color and light.', '2011-03-16 12:43:11.000000', NULL, 1),
(6353281, 940228, 113419, '<td valign="top">waldo is only barely noticeable</td>', 'waldo is only barely noticeable', '2011-03-16 12:44:14.000000', NULL, 1),
(6353284, 940810, 113419, '<td valign="top">gorgeous!  love the brown and green, the neck of a barely noticeable bottle with one single drop - this is one water drop image that I FOR REAL like</td>', 'gorgeous!  love the brown and green, the neck of a barely noticeable bottle with one single drop - this is one water drop image that I FOR REAL like', '2011-03-16 12:45:42.000000', NULL, 1),
(6353288, 940863, 113419, '<td valign="top">i think this image is too bright</td>', 'i think this image is too bright', '2011-03-16 12:46:49.000000', NULL, 1),
