(6353307, 940857, 123601, '<td valign="top">way to bright</td>', 'way to bright', '2011-03-16 13:02:20.000000', NULL, 1),
(6353308, 940871, 128471, '<td valign="top">Its too bright</td>', 'Its too bright', '2011-03-16 13:03:07.000000', NULL, 1),
(6353317, 940121, 117474, '<td valign="top">I''m gonna update this from a 9 to a 10 and favourite it. <br/>I''m not quite sure what it is I like about it... but I like that something a lot. Fantastic work!</td>', 'I''m gonna update this from a 9 to a 10 and favourite it. I''m not quite sure what it is I like about it... but I like that something a lot. Fantastic work!', '2011-03-16 13:13:14.000000', NULL, 1),
(6353360, 940969, 127901, '<td valign="top">This is a very creative photo. I keep finding myself going back and looking at it. Great job!</td>', 'This is a very creative photo. I keep finding myself going back and looking at it. Great job!', '2011-03-16 14:06:22.000000', NULL, 1),
(6353433, 940123, 118396, '<td valign="top">I would have liked this better if it was a little crisper focus.  Also, the scuffed floor makes me think about dirt and water should be clean.  Just my opinion though.  I do like that the water bottle in the reflection looks larger than the actual bottle.</td>', 'I would have liked this better if it was a little crisper focus.  Also, the scuffed floor makes me think about dirt and water should be clean.  Just my opinion though.  I do like that the water bottle in the reflection looks larger than the actual bottle.', '2011-03-16 14:52:57.000000', NULL, 1),
(6353435, 940129, 118396, '<td valign="top">I don''t really like the soft focus and I''m a little grossed out.</td>', 'I don''t really like the soft focus and I''m a little grossed out.', '2011-03-16 14:53:37.000000', NULL, 1),
(6353437, 940132, 118396, '<td valign="top">I think I might have appreciated this concept if it wasn''t set up in the sink with a dirty sponge in the background.  If you had been able to crop out the date stamp and the distracting objects around the edge, I think this would have been a much higher rated photo.</td>', 'I think I might have appreciated this concept if it wasn''t set up in the sink with a dirty sponge in the background.  If you had been able to crop out the date stamp and the distracting objects around the edge, I think this would have been a much higher rated photo.', '2011-03-16 14:55:46.000000', NULL, 1),
(6353440, 940952, 118396, '<td valign="top">This image is a bit too abstract for me to make out that it''s a water bottle.  Neat texture though!</td>', 'This image is a bit too abstract for me to make out that it''s a water bottle.  Neat texture though!', '2011-03-16 14:56:45.000000', NULL, 1),
(6353441, 940968, 118396, '<td valign="top">This photo is so busy with the magazines, that my focus was on everything except the water bottles.  I would have scored it higher if you had cut out the left half of the picture.  Just my opinion though!</td>', 'This photo is so busy with the magazines, that my focus was on everything except the water bottles.  I would have scored it higher if you had cut out the left half of the picture.  Just my opinion though!', '2011-03-16 14:57:56.000000', NULL, 1),
(6353444, 940127, 118396, '<td valign="top">This image feels like there was a lack of effort put into it.  This looks like something I could take with my cell phone at my office.  I probably would have scored it higher if you had cut out the lights/ceiling tiles.  I do like the tilt/perspective.</td>', 'This image feels like there was a lack of effort put into it.  This looks like something I could take with my cell phone at my office.  I probably would have scored it higher if you had cut out the lights/ceiling tiles.  I do like the tilt/perspective.', '2011-03-16 14:59:31.000000', NULL, 1),
(6353447, 940124, 118396, '<td valign="top">I think the reason I didn''t give this image a higher score is because it looks like very little effort was put into this entry.  Most anyone could open their refrigerator and click off a shot.  It doesn''t really hold any interest for me.  Also, whatever is in the drawer is a little distracting.</td>', 'I think the reason I didn''t give this image a higher score is because it looks like very little effort was put into this entry.  Most anyone could open their refrigerator and click off a shot.  It doesn''t really hold any interest for me.  Also, whatever is in the drawer is a little distracting.', '2011-03-16 15:03:15.000000', NULL, 1),
(6353448, 940863, 118396, '<td valign="top">The scenery is beautiful - personally, I''m just a little thrown by the tilt of the water bottle.  I would have enjoyed this image more if the bottle had been straight up and down.  Just my opinion.</td>', 'The scenery is beautiful - personally, I''m just a little thrown by the tilt of the water bottle.  I would have enjoyed this image more if the bottle had been straight up and down.  Just my opinion.', '2011-03-16 15:04:27.000000', NULL, 1),
(6353455, 940174, 118389, '<td valign="top">i like the idea</td>', 'i like the idea', '2011-03-16 15:17:24.000000', NULL, 1),
(6353459, 940811, 118389, '<td valign="top">this challenge winner :) nice lighting, and shot!</td>', 'this challenge winner :) nice lighting, and shot!', '2011-03-16 15:23:37.000000', NULL, 1),
(6353502, 940875, 111569, '<td valign="top">Great capture &amp; DOF</td>', 'Great capture & DOF', '2011-03-16 16:00:41.000000', NULL, 1),
