(6353647, 940952, 128200, '<td valign="top">I can''t tell what this is. I spent a good five minutes on it and gave up.</td>', 'I can''t tell what this is. I spent a good five minutes on it and gave up.', '2011-03-16 18:23:37.000000', NULL, 1),
(6353713, 940129, 108857, '<td valign="top">nice idea, very grainy and out of focus.</td>', 'nice idea, very grainy and out of focus.', '2011-03-16 19:27:46.000000', NULL, 1),
(6353714, 940803, 108857, '<td valign="top">Although a few others had similar ideas in this challenge, yours is by far the best executed.  well done.</td>', 'Although a few others had similar ideas in this challenge, yours is by far the best executed.  well done.', '2011-03-16 19:28:45.000000', NULL, 1),
(6353721, 940138, 108857, '<td valign="top">the lighting seems a bit harsh (the problem with natural lighting)</td>', 'the lighting seems a bit harsh (the problem with natural lighting)', '2011-03-16 19:46:48.000000', NULL, 1),
(6353725, 939870, 55283, '<td valign="top">I think I''d like it more if it were more abstract, without the bottle edge, which keeps drawing my eye out of frame.</td>', 'I think I''d like it more if it were more abstract, without the bottle edge, which keeps drawing my eye out of frame.', '2011-03-16 19:49:20.000000', NULL, 1),
(6353729, 940126, 55283, '<td valign="top">The soft focus and distracting shoe reflections bring down your score from me.</td>', 'The soft focus and distracting shoe reflections bring down your score from me.', '2011-03-16 19:51:43.000000', NULL, 1),
(6353730, 940828, 55283, '<td valign="top">Nice stop action</td>', 'Nice stop action', '2011-03-16 19:52:12.000000', NULL, 1),
(6353734, 939923, 55283, '<td valign="top">I''d like it more if I had something to look at at the end of the "tunnel" besides the white light/moon.</td>', 'I''d like it more if I had something to look at at the end of the "tunnel" besides the white light/moon.', '2011-03-16 19:54:44.000000', NULL, 1),
(6353735, 940825, 114225, '<td valign="top">The center based composition was the right choice here. Adds great balance to the photo.</td>', 'The center based composition was the right choice here. Adds great balance to the photo.', '2011-03-16 19:55:28.000000', NULL, 1),
(6353736, 940802, 55283, '<td valign="top">Seems like the focus point is on the backpack more than the bottle. It gets soft at the lid.</td>', 'Seems like the focus point is on the backpack more than the bottle. It gets soft at the lid.', '2011-03-16 19:56:37.000000', NULL, 1),
(6353737, 940863, 114225, '<td valign="top">I like the scene and how you are going for a advertisement type shot. The titled bottle is really bothering me though. Seems to throw off the balance of the scene.</td>', 'I like the scene and how you are going for a advertisement type shot. The titled bottle is really bothering me though. Seems to throw off the balance of the scene.', '2011-03-16 19:57:14.000000', NULL, 1),
(6353738, 940662, 55283, '<td valign="top">The high key tone of this made it take a minute for me to see that those were other bottles, not ice cubes. I like it.</td>', 'The high key tone of this made it take a minute for me to see that those were other bottles, not ice cubes. I like it.', '2011-03-16 19:57:49.000000', NULL, 1),
(6353740, 940803, 55283, '<td valign="top">The violet being more opaque than the other colors detracts from an otherwise nice setup.</td>', 'The violet being more opaque than the other colors detracts from an otherwise nice setup.', '2011-03-16 19:59:42.000000', NULL, 1),
(6353741, 940835, 55283, '<td valign="top">A little too noisy for me.</td>', 'A little too noisy for me.', '2011-03-16 20:01:10.000000', NULL, 1),
(6353742, 940849, 55283, '<td valign="top">Fun. I love light painting shots. A more consistent rainbow would probably get you a 9. As is, 7.</td>', 'Fun. I love light painting shots. A more consistent rainbow would probably get you a 9. As is, 7.', '2011-03-16 20:03:27.000000', NULL, 1),
(6353745, 940020, 55283, '<td valign="top">I like the idea, but I''m not a fan of the way dof is used here. Sorry.</td>', 'I like the idea, but I''m not a fan of the way dof is used here. Sorry.', '2011-03-16 20:05:18.000000', NULL, 1),
(6353747, 940127, 55283, '<td valign="top">This seems like you were bored at school/work and took a phone pic. There is nothing there to really grab my interest. Sorry.</td>', 'This seems like you were bored at school/work and took a phone pic. There is nothing there to really grab my interest. Sorry.', '2011-03-16 20:06:44.000000', NULL, 1),
(6353750, 940409, 55283, '<td valign="top">You''d have gotten another point from me if the string and holes for the blinds weren''t visible in the top right.</td>', 'You''d have gotten another point from me if the string and holes for the blinds weren''t visible in the top right.', '2011-03-16 20:07:50.000000', NULL, 1),
(6353752, 940923, 55283, '<td valign="top">My guess is that you''re score is getting killed, but I like it. It''s hard to do something interesting with a water bottle.</td>', 'My guess is that you''re score is getting killed, but I like it. It''s hard to do something interesting with a water bottle.', '2011-03-16 20:08:46.000000', NULL, 1),
(6353758, 940295, 55283, '<td valign="top">The nest in the front seems much sharper than the cap strap. It may be illusory, though. I had a shot that everyone thought was soft, but it was the nature of the smooth subject that made it seem so. I''ll give you the benefit of the doubt.</td>', 'The nest in the front seems much sharper than the cap strap. It may be illusory, though. I had a shot that everyone thought was soft, but it was the nature of the smooth subject that made it seem so. I''ll give you the benefit of the doubt.', '2011-03-16 20:11:26.000000', NULL, 1),
(6353763, 940810, 55283, '<td valign="top">Looks more like glass, than a water bottle. Maybe vodka? A good shot nonetheless. Maybe a bit oversharpened. Could be compression issue, though. Tie goes to the shooter. 8.</td>', 'Looks more like glass, than a water bottle. Maybe vodka? A good shot nonetheless. Maybe a bit oversharpened. Could be compression issue, though. Tie goes to the shooter. 8.', '2011-03-16 20:13:22.000000', NULL, 1),
(6353766, 940928, 55283, '<td valign="top">Interesting concept. I hope you have the extra insurance for when the condensation forms on the outside.</td>', 'Interesting concept. I hope you have the extra insurance for when the condensation forms on the outside.', '2011-03-16 20:14:46.000000', NULL, 1),
(6353767, 940665, 108857, '<td valign="top">quite a striking image.</td>', 'quite a striking image.', '2011-03-16 20:14:59.000000', NULL, 1),
(6353770, 940969, 114225, '<td valign="top">I like your lighting, and how the guy on top is lit by the "energy" in the bottle.</td>', 'I like your lighting, and how the guy on top is lit by the "energy" in the bottle.', '2011-03-16 20:17:24.000000', NULL, 1),
(6353771, 940263, 114225, '<td valign="top">The vest resting against the tire adds a lot of story to this shot.</td>', 'The vest resting against the tire adds a lot of story to this shot.', '2011-03-16 20:18:52.000000', NULL, 1),
(6353772, 939897, 55283, '<td valign="top">A nice stop action shot, no doubt, but it seems more like a soda bottle than a water bottle given the liquid color and the material of the bottle. Maybe they do glass water bottles elsewhere in the world, but it''s not something I''m familiar with, except for Perrier, which I only know to come in green bottles. Either way, the red hurts you more than the glass in my score. 6</td>', 'A nice stop action shot, no doubt, but it seems more like a soda bottle than a water bottle given the liquid color and the material of the bottle. Maybe they do glass water bottles elsewhere in the world, but it''s not something I''m familiar with, except for Perrier, which I only know to come in green bottles. Either way, the red hurts you more than the glass in my score. 6', '2011-03-16 20:19:07.000000', NULL, 1),
(6353775, 940295, 114225, '<td valign="top">Nice details and a cool looking bottle.</td>', 'Nice details and a cool looking bottle.', '2011-03-16 20:19:58.000000', NULL, 1),
(6353776, 940865, 55283, '<td valign="top">I''m torn. I really like this, but it is clearly not a water bottle. 6 for you.</td>', 'I''m torn. I really like this, but it is clearly not a water bottle. 6 for you.', '2011-03-16 20:20:05.000000', NULL, 1),
(6353777, 940744, 55283, '<td valign="top">I think the Nestle bottles take away from this. I understand your concept, but I think you would have fared better to just take a nice sharp shot of the glass bottle. Not everyone has access to a prop like that and I think it would have stood out. As is, it battles for attention with Nestle bottles that many other people used.</td>', 'I think the Nestle bottles take away from this. I understand your concept, but I think you would have fared better to just take a nice sharp shot of the glass bottle. Not everyone has access to a prop like that and I think it would have stood out. As is, it battles for attention with Nestle bottles that many other people used.', '2011-03-16 20:22:39.000000', NULL, 1),
(6353782, 940724, 55283, '<td valign="top">I don''t get the connection. The cap reminds you of a snout and you ran with it from there? Regardless, nothing seems to be in focus. Sorry, it''s not for me. 3</td>', 'I don''t get the connection. The cap reminds you of a snout and you ran with it from there? Regardless, nothing seems to be in focus. Sorry, it''s not for me. 3', '2011-03-16 20:26:03.000000', NULL, 1),
(6353783, 940897, 55283, '<td valign="top">Seems soft at the spout.</td>', 'Seems soft at the spout.', '2011-03-16 20:26:41.000000', NULL, 1),
(6353784, 940887, 55283, '<td valign="top">Nice and sharp where it needs to be. Well lit.</td>', 'Nice and sharp where it needs to be. Well lit.', '2011-03-16 20:27:46.000000', NULL, 1),
(6353785, 940857, 55283, '<td valign="top">Don''t love it. Don''t hate it. I guess that leaves you with a 5.</td>', 'Don''t love it. Don''t hate it. I guess that leaves you with a 5.', '2011-03-16 20:29:16.000000', NULL, 1),
(6353786, 940676, 55283, '<td valign="top">I understand that they have water in them, so technically they <i>are</i> water bottles. If you had done the same shot with actual water bottles, I''d score it better.</td>', 'I understand that they have water in them, so technically they are water bottles. If you had done the same shot with actual water bottles, I''d score it better.', '2011-03-16 20:31:15.000000', NULL, 1),
(6353789, 940799, 55283, '<td valign="top">Fun shot. He could use some fill flash or a reflector, though. Maybe a different angle. The monkey bars are the only thing screaming "play time" to me, but as is, they are distracting and pulling me out of the frame. If you had rotated 90 degrees and had him at the bottom of the slide, it might''ve worked better (for me).</td>', 'Fun shot. He could use some fill flash or a reflector, though. Maybe a different angle. The monkey bars are the only thing screaming "play time" to me, but as is, they are distracting and pulling me out of the frame. If you had rotated 90 degrees and had him at the bottom of the slide, it might''ve worked better (for me).', '2011-03-16 20:34:35.000000', NULL, 1),
(6353790, 940530, 55283, '<td valign="top">The color doesn''t scream water to me, but I won''t hold that against you. I would have cropped tighter to get the small green from the background bottle out of frame.</td>', 'The color doesn''t scream water to me, but I won''t hold that against you. I would have cropped tighter to get the small green from the background bottle out of frame.', '2011-03-16 20:35:55.000000', NULL, 1),
(6353791, 940678, 55283, '<td valign="top">Don''t love it. Don''t hate it. I guess that means you get a 5.</td>', 'Don''t love it. Don''t hate it. I guess that means you get a 5.', '2011-03-16 20:36:57.000000', NULL, 1),
(6353794, 940732, 55283, '<td valign="top">Not very exciting and I had to hunt for any actual water bottles. My eye is drawn to the guy on the phone more than anything.</td>', 'Not very exciting and I had to hunt for any actual water bottles. My eye is drawn to the guy on the phone more than anything.', '2011-03-16 20:41:09.000000', NULL, 1),
(6353796, 940137, 55283, '<td valign="top">Focus seems soft</td>', 'Focus seems soft', '2011-03-16 20:41:52.000000', NULL, 1),
(6353797, 940432, 55283, '<td valign="top">That is a big jug of water, but not all that interesting.</td>', 'That is a big jug of water, but not all that interesting.', '2011-03-16 20:44:23.000000', NULL, 1),
(6353799, 940886, 55283, '<td valign="top">I think this would have been more effective without the water in the shot, but still, I like it. Also, your horizon is tilted slightly.</td>', 'I think this would have been more effective without the water in the shot, but still, I like it. Also, your horizon is tilted slightly.', '2011-03-16 20:45:52.000000', NULL, 1),
(6353802, 940266, 55283, '<td valign="top">I would have liked a deeper dof to get the mouth of the bottle in focus also.</td>', 'I would have liked a deeper dof to get the mouth of the bottle in focus also.', '2011-03-16 20:46:53.000000', NULL, 1),
(6353803, 940818, 55283, '<td valign="top">Was this a cameraphone shot? Very noisy.</td>', 'Was this a cameraphone shot? Very noisy.', '2011-03-16 20:47:37.000000', NULL, 1),
(6353804, 940800, 55283, '<td valign="top">This is Rorschach-esque. I won''t tell you what I see, but I had fun looking.</td>', 'This is Rorschach-esque. I won''t tell you what I see, but I had fun looking.', '2011-03-16 20:49:54.000000', NULL, 1),
(6353805, 940752, 55283, '<td valign="top">Interesting lighting setup</td>', 'Interesting lighting setup', '2011-03-16 20:50:17.000000', NULL, 1),
(6353806, 940136, 55283, '<td valign="top">Does he have Spock ears?</td>', 'Does he have Spock ears?', '2011-03-16 20:50:55.000000', NULL, 1);
